import unittest

from solucao import calcular


class TestONomeSoViveDentro(unittest.TestCase):
    def test_calcula_cinco(self):
        """a caixa devolve 15 quando recebe 5"""
        self.assertEqual(calcular(5), 15)

    def test_calcula_zero(self):
        """a caixa devolve 10 quando recebe 0"""
        self.assertEqual(calcular(0), 10)

    def test_calcula_cem(self):
        """a caixa devolve 110 quando recebe 100"""
        self.assertEqual(calcular(100), 110)

